    // with a second already-approved fictional artwork, never a customer image.
    const mediaContext = await contextFor(390); const mediaPage = await mediaContext.newPage();
    await load(mediaPage);
    const replacement = 'data:image/webp;base64,' + fs.readFileSync(path.join(root, 'frontend/public/copy-trading/avatars/panda-block.webp')).toString('base64');
    fixture.ownerRows.get('qa-ksenia-owner').avatarUrl = replacement;
